import json
from pathlib import Path

from mock_api import TRACE, search
from query_audit import build_rejection
from timezone_defaults import MISSING_TZ_POLICY
from window_projection import build_window, parse_bound, utc_pair, wall_clock_pair


def _normalized_values(window):
    start_utc, end_utc = utc_pair(window)
    return {
        "start_date_utc": start_utc.isoformat().replace("+00:00", "Z"),
        "end_date_utc": end_utc.isoformat().replace("+00:00", "Z"),
        "naive_timestamp_policy": MISSING_TZ_POLICY,
    }


def _error(param, message, payload, normalized=None):
    error = build_rejection(param, message, payload)
    if normalized is not None:
        error["normalized"] = normalized
    return error


def validate_range(payload):
    if not isinstance(payload, dict):
        return [_error("query", "query must be an object", payload)]
    if "start_date" not in payload:
        return [_error("start_date", "is required", payload)]
    try:
        parse_bound(payload["start_date"])
    except (TypeError, ValueError) as exc:
        return [_error("start_date", f"invalid ISO 8601 timestamp: {exc}", payload)]
    if "end_date" in payload:
        try:
            parse_bound(payload["end_date"])
        except (TypeError, ValueError) as exc:
            return [_error("end_date", f"invalid ISO 8601 timestamp: {exc}", payload)]
    try:
        window = build_window(payload)
    except (KeyError, TypeError, ValueError) as exc:
        return [_error("date_range", f"invalid ISO 8601 range: {exc}", payload)]

    if "end_date" not in payload:
        return []

    start_utc, end_utc = utc_pair(window)
    start_local, end_local = wall_clock_pair(window)
    normalized = _normalized_values(window)
    errors = []

    # The service compares instants, so compare aware UTC values rather than
    # the source strings or their local calendar days.
    if end_utc < start_utc:
        errors.append(
            _error(
                "date_range",
                "end_date must be greater than or equal to start_date after UTC normalization",
                payload,
                normalized,
            )
        )

    # A fall-back overlap is intentionally treated as ambiguous when the two
    # offsets identify the repeated local hour and the wall clock moves back.
    if (
        start_local.date() == end_local.date()
        and start_local.hour == end_local.hour
        and window["start"].utcoffset() != window["end"].utcoffset()
        and end_local < start_local
    ):
        errors.append(
            _error(
                "date_range",
                "ambiguous fall-back DST range: end wall-clock time is earlier than start",
                payload,
                normalized,
            )
        )
    return errors


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

